insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 20, 'Tu vês muitas coisas, porém não as guardas; mesmo abrindo os ouvidos, contudo nada ouve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 21, 'O SENHOR se agradou, por causa de sua justiça, em engrandecer [sua] lei, e em fazê [-la] gloriosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 22, 'Mas [este] é um povo roubado e saqueado; todos estão enlaçados em covas, e escondidos em cárceres; são postos como despojos, e ninguém há que os resgate; estão como [objetos] de roubo, e ninguém diz “Restitui [-os] ”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 23, 'Quem dentre vós dá ouvidos a isto? [Quem] presta atenção e ouve o que há de ser no futuro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 24, 'Quem entregou a Jacó como roubo, e a Israel a ladrões? Por acaso não foi o SENHOR, aquele contra quem pecamos? Pois não queriam andar em seus caminhos, e não deram ouvidos à sua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 25, 'Por isso ele derramou sobre eles o furor de sua ira, e a força da guerra; e os pôs em labaredas ao redor; porém [ainda assim] não entenderam; e ele os pôs para queimar, porém [ainda assim] não puseram [nisso] o coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 1, 'Porém agora assim diz o SENHOR, o teu Criador, ó Jacó, e o teu Formador, ó Israel: Não temas, porque eu te resgatei; chamei a ti por teu nome; tu és meu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 2, 'Quando passares pelas águas, estarei contigo; e [ao passares] pelos rios, eles não te submergirão; quando passares pelo fogo, não te queimarás, nem a chamas arderão em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 3, 'Porque eu sou o SENHOR teu Deus, o Santo de Israel, teu Salvador; dei ao Egito, a Cuxe, e a Seba como teu resgate, em teu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 4, 'Visto que foste precioso em meus olhos, [assim] foste glorificado, e eu te amei; por isso dei homens em troca de ti, e povos em troca de tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 5, 'Não temas, pois estou contigo; eu trarei tua semente desde o oriente, e te ajuntarei desde o ocidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 6, 'Direi ao norte: Dá!, E ao sul: Não retenhas! Trazei meus filhos de longe, e minhas filhas desde os confins da terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 7, 'Todos os chamados do meu nome, e os que criei para minha gloria; eu os formei; sim, eu os fiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 8, 'Trazei ao povo cego, que tem olhos; e aos surdos, que tem ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 9, 'Todas as nações se reúnam, e os povos se ajuntem. Quem deles isto isto anuncia, e nos faz ouvir as coisas do passado? Mostrem suas testemunhas, para que se justifiquem, e se ouça, e se diga: É verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 10, 'Vós sois minhas testemunhas (diz o SENHOR); e meu servo, a quem escolhi; para que saibais, e creiais em mim, e entendais que eu sou o próprio, e [que] antes de mim nenhum Deus se formou, e depois de minha nenhum haverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 11, 'Eu, eu sou o SENHOR; e fora de mim não há salvador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 12, 'Eu anunciei, eu salvei, e eu fiz ouvir, e deus estrangeiro não houve entre vós, e vós sois minhas testemunhas, (diz o SENHOR), que eu sou Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 13, 'E desde antes de haver dia, eu o sou; e ninguém há que possa livrar das minhas mãos. Eu estou agindo, quem pode impedir?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 14, 'Assim diz o SENHOR o teu Redentor, o Santo de Israel: Por causa de vós eu enviei [inimigos] a Babilônia, e a todos eu os fiz descerem [como] fugitivos, inclusive os Caldeus, nos navios em que se orgulhavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 15, 'Eu sou o SENHOR, vosso Santo; o Criador de Israel, o vosso Rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 16, 'Assim diz o SENHOR, aquele que preparou no mar um caminho, e nas águas impetuosas uma vereda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 17, 'Aquele que trouxe carruagens e cavalos, exército e forças; [todos] juntamente caíram, e não mais se levantaram; estão extintos, foram apagados como um pavio:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 18, 'Não vos lembreis das coisas passadas, nem considereis as antigas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 19, 'Eis que farei uma coisa nova, agora surgirá; por acaso não a reconhecereis? Pois porei um caminho no deserto, [e] rios na terra vazia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 20, 'Os animais do campo me honrarão; os chacais e os filhotes de avestruz; porque porei águas no deserto, rios na terra vazia, para dar de beber a meu povo, meu escolhido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 21, 'Este povo formei para mim, eles declararão louvor a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 22, 'Porém tu não me invocaste, ó Jacó; pois te cansaste de mim, ó Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 23, 'Não me trouxeste o gado miúdo de teus holocaustos, nem me honraste [com] teus sacrifícios; eu não vos oprimi com ofertas, nem te cansei com incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 24, 'Não me compraste com dinheiro cana aromática, nem me saciaste com a gordura de teus sacrifícios; mas me oprimiste com teus pecados, [e] me cansaste com tuas maldades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 25, 'Eu, eu sou o que anulo tuas transgressões por causa de mim; e te teus pecados eu não me lembro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 26, 'Faze-me lembrar, entremos em juízo juntos; mostra [teus argumentos] ,para que possas te justificar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 27, 'Teu primeiro pai pecou; e teus intérpretes transgrediram contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 43, 28, 'Por isso profanei os líderes do santuário, e entreguei Jacó à desgraça, e Israel à humilhação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 1, 'Agora, pois, ouve, ó Jacó, meu servo; tu, ó Israel, a quem escolhi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 2, 'Assim diz o SENHOR, aquele que te fez, e te formou desde o ventre, que te socorre: não temas, ó Jacó, meu servo; tu Jesurum, a quem escolhi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 3, 'Porque derramarei água sobre o sedento, e rios sobre a terra seca; derramarei meu Espírito sobre tua semente, e minha bênção sobre teus descendentes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 4, 'E brotarão entre a erva, como salgueiros junto a ribeiros de águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 5, 'Um dirá: Eu sou do SENHOR; e outro se chamará pelo nome de Jacó; e um [terceiro] escreverá [em] sua mão: Eu sou do SENHOR, e tomará para si o nome de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 6, 'Assim diz o SENHOR, Rei de Israel, e seu Redentor, o SENHOR dos exércitos:Eu sou o primeiro, e sou o último; e além de mim não há Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 7, 'Quem, como eu, anunciará isto? Que declare e explique para mim, visto que determinei um povo eterno! Anunciem-lhes as coisas futuras, as que estão para vir!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 8, 'Não vos assombreis, nem temais; por acaso eu não vos contei e anunciei com antecedência? Pois vós sois minhas testemunhas. Por acaso há outro Deus além de mim? Não há outra Rocha, não que eu conheça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 9, 'Todos os que formam imagens de escultura são nada, e as coisas que eles se agradam são de nenhum proveito; e elas mesmas são suas testemunhas: nada veem, nem entendem; por isso serão envergonhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 10, 'Quem é que forma um deus e funde uma imagem de escultura que não lhe tem proveito algum?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 11, 'Eis que todos os companheiros dele serão envergonhados, pois os artífices nada são além de homens. Ajuntem-se todos, [e] fiquem de pé; eles se assombrarão, e juntamente serão envergonhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 12, 'O ferreiro, [com] a ferramenta de corte, trabalha nas brasas, e forma [o ídolo] com martelos; e ele o faz com a força de seu braço; ele, porém, tem fome e perde as forças, e [se] não beber água, desfalece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 13, 'O carpinteiro estende a linha de medir, [e] o desenha com um marcador; ele o confecciona com formões, e o desenha com um compasso; e o faz à semelhança de um homem, conforme a beleza humana, para habitar numa casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 14, 'Ele corta para si cedros, e toma um cipreste ou um carvalho, e reserva para si das árvores da floresta; ele planta um pinheiro, e a chuva [o] faz crescer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 15, 'Então [tal madeira] servirá ao homem para queimar, e toma parte deles para se aquecer, e os acende, e aquece o pão; ele também faz um deus, e o adora; fabrica dela uma imagem de escultura, e se prostra diante dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 16, 'Sua metade ele queima no fogo; com a [outra] metade como carne; prepara assado, e [dele] se sacia; também se esquenta, e diz: Ah! Já me aqueci! Já vi o fogo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 17, 'Então do resto ele faz um deus, para imagem de escultura para si; ele se ajoelha a ela, e a adora, e ora a ela, e diz: Livra-me, pois tu és meu deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 18, 'Eles nada sabem, nem entendem; porque seus olhos foram encobertos para que não vejam; [e] seus corações, para que não entendam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 19, 'E nenhum deles pensa [sobre isso] em seu coração, e não tem conhecimento nem entendimento para dizer: A metade queimei no fogo; e aqueci pão sobre suas brasas; assei carne, e a comi; e faria eu do resto uma abominação? Prostraria eu ao que saiu de uma árvore?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 20, 'Ele se alimenta de cinzas; [seu] coração enganado o desviou, de modo que ele já não pode livrar a sua alma, nem dizer: Por acaso não é uma mentira [o que há] na minha mão direita?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 21, 'Lembra-te destas coisas, ó Jacó e Israel, pois tu és meu servo; eu te formei. Meu servo és, ó Israel; eu não me esquecerei de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 22, 'Eu elimino tuas transgressões como a névoa, e teus pecados como a nuvem; volta a mim, pois eu já te resgatei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 23, 'Cantai louvores, vós céus, porque o SENHOR [assim] fez; gritai de alegria, vós partes baixas da terra; vós montes, fazei ruídos de júbilo, [também] vós bosques, e todas as árvores neles; porque o SENHOR regatou a Jacó, e glorificou a si mesmo em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 24, 'Assim diz o SENHOR, o teu redentor, aquele que te formou desde o ventre: Eu sou o SENHOR que tudo faço; que sozinho estico os céus, e que estendo a terra por mim mesmo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 25, 'Que desfaço os sinais dos inventores de mentiras, e faço de todos aos adivinhos; que faço aos sábios retrocederem, e torno o conhecimento deles em loucura;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 26, '[Sou aquele] que confirma a palavra de seu servo, e cumpre o conselho de seus mensageiros; que diz a Jerusalém: Tu serás habitada; E às cidades de Judá: Sereis reconstruídas; e eu erguerei seus lugares arruinados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 27, 'Que diz à profundeza: Seca-te; e eu secarei teus rios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 44, 28, 'Que diz de Ciro: Ele é meu pastor, e cumprirá toda a minha vontade, dizendo à Jerusalém: Serás edificada; e ao Templo: Terás posto teu fundamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 1, 'Assim diz o SENHOR a seu ungido, Ciro, ao qual tomou pela sua mão direita, para abater as nações diante dele, e tirar a proteção dos lombos dos reis; para abrir diante de sua presença as portas, e as portas não se fecharão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 2, 'Eu irei adiante de ti, e nivelarei os caminhos acidentados; quebrarei as portas de bronze, e despedaçarei os ferrolhos de ferro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 3, 'E te darei os tesouros das escuridões, e as riquezas escondidas; para que possas saber que eu sou o SENHOR, que [te] chama pelo teu nome, o Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 4, 'Em favor de meu servo Jacó e de meu escolhido Israel, eu te chamei pelo teu nome; eu te pus teu título, ainda que tu não me conhecesses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 5, 'Eu sou o SENHOR, e ninguém mais; fora de mim não há Deus; eu te revestirei, ainda que tu não me conheças;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 6, 'Para que saibam desde o oriente e desde o ocidente que fora de mim não há outro. Eu sou o SENHOR, e ninguém mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 7, 'Eu formo a luz e crio as trevas; eu faço a paz, e crio a adversidade; eu, o SENHOR, faço todas estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 8, 'Gotejai vós, céus, de cima, e as nuvens destilem justiça; abra-se a terra, e produza-se salvação, e a justiça juntamente frutifique; eu, o SENHOR, as criei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 9, 'Ai daquele que briga com seu formador: [apenas] um caco entre outros cacos de barro! Por acaso o barro dirá ao seu formador: Que fazes? Ou tua obra: Não tem mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 10, 'Ai daquele que diz ao pai: O que é que tu geras? E à mulher: O que é que tu fazes nascer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 11, 'Assim diz o SENHOR, o Santo de Israel, e seu formador: Perguntai-me sobre as coisas futuras; [por acaso] me dais ordens sobre os meus filhos, e sobre as obras de minhas mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 12, 'Eu fiz a terra, e criei nela o homem; fui eu, minhas próprias mãos estenderam os céus, e dei ordens sobre todo o seu exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 13, 'Eu o despertei em justiça, e todos os seus caminhos endireitarei; ele edificará minha cidade, e soltará meus cativos; não por preço, nem por subornos,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 14, 'Assim diz o SENHOR: O trabalho do Egito, e o comércio dos cuxitas e dos sabeus, homens de alta estatura, passarão a ti, e serão teus; eles irão após ti, passarão acorrentados; e a ti se prostrarão, a ti suplicarão, [dizendo] : Certamente Deus está contigo, e nenhum outro Deus há.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 15, 'Verdadeiramente tu és o Deus que se encobre; o Deus de Israel, o Salvador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 16, 'Serão envergonhados, e também humilhados, todos eles; juntamente irão embora com vergonha os que fabricam imagens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 17, '[Mas] Israel é salvo pelo SENHOR, [com] salvação eterna; não sereis envergonhados nem humilhados para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 18, 'Porque assim diz o SENHOR, que criou os céus, o Deus que formou a terra, e a fez; ele a firmou, não a criou [para ser] vazia, [ao contrário] ,criou para que fosse habitada: Eu sou o SENHOR, e ninguém mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 19, 'Não falei em oculto, [nem] em algum lugar escuro da terra; não disse à semente de Jacó: Buscai-me, em vão; eu sou o SENHOR, que fala justiça, [e] anuncio coisas corretas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 20, 'Ajuntai-vos, e vinde; achegai-vos juntamente os que escapastes das nações. Os que carregam suas imagens de escultura de madeira, e rogam a um Deus que não pode salvar, nada conhecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 21, 'Anunciai, e achegai-vos; e consultai juntamente em conselho; quem fez ouvir isto desde a antiguidade? [Quem] desde então tem anunciado? Por acaso não sou eu, o SENHOR? E não há ouro Deus além de mim, Deus justo e Salvador; ninguém, a não ser eu [mesmo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 22, 'Virai-vos a mim, e sede salvos, vós todos os limites da terra; porque eu sou Deus, e ninguém mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 23, 'Por mim mesmo tenho jurado; já saiu da minha boca palavra de justiça, e não voltará atrás: que a mim se dobrará todo joelho, e toda língua prestará juramento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 24, 'De mim se dirá: Certamente no SENHOR há justiça e poder; Até a ele chegarão, mas serão envergonhados todos os que o odeiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 45, 25, '[Porém] no SENHOR todos [os que são da] semente de Israel serão justificados e se gloriarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 1, 'Bel se abaixa, Nebo se curva; seus ídolos são postos sobre os animais e sobre o gado; as cargas de vossos fardos são exaustivas para os [animais] já cansados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 2, 'Juntamente se encurvam e se abaixam; não podem salvar a carga, mas eles mesmos vão ao cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 3, 'Ouvi-me, ó casa de Jacó, e todo o restante da casa de Israel; vós a quem eu carreguei desde o ventre, a quem levei desde o útero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 4, 'E até [vossa] velhice eu serei o mesmo, e ainda até [à idade dos] cabelos grisalhos eu [vos] carregarei; eu [vos] fiz, e eu [vos] levarei; eu [vos] carregarei e [vos] livrarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 5, 'A quem me considerareis semelhante, e com quem [me] igualareis, e me comparareis, para que sejamos semelhantes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 6, 'Eles gastam o ouro da bolsa, e pesam a prata com balanças; pagam ao ourives, e daquilo ele faz um deus, e se prostram e adoram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 7, 'Sobre os ombros o temam, o carregam, e o põem em seu lugar; ali ele fica, de seu lugar não se move; e se chamarem por ele, resposta nenhuma ele dá, nem o livra de sua aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 8, 'Lembrai-vos disto, e sede corajosos; fazei memória disso no coração, ó transgressores!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 9, 'Lembrai-vos das coisas passadas desde a antiguidade; porque eu sou Deus, e nenhum outro deus há, e ninguém há semelhante a mim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 10, 'Que declaro o fim desde o princípio, e desde a antiguidade as coisas que ainda não aconteceram; que digo: Minha intenção será firme, e farei toda a minha vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 11, 'Que chamo a ave de rapina desde o oriente, ao homem da minha intenção desde as terras distantes; porque assim disse; e assim o cumprirei; eu [o] formei, também o farei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 12, 'Ouvi-me, ó duros de coração; vós que estais longe da justiça:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 46, 13, 'Eu trago para perto minha justiça, ela não ficará longe; e minha salvação não tardará; mas porei salvação em Sião, a Israel minha glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 1, 'Desce, e senta-te no pó da terra, ó virgem filha da Babilônia; senta-te no chão; já não há [mais] trono, ó filha dos caldeus; pois nunca mais serás chamada de tenra e delicada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 2, 'Toma as pedras de moer, e mói farinha; descobre o teu véu, expõe as pernas, descobre as coxas, [e] passa os rios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 3, 'Tua nudez será descoberta, e tua vergonha será vista; tomarei vingança, e a ninguém pouparei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 4, 'O nome de nosso Redentor é o SENHOR dos exércitos, o Santo de Israel!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 5, 'Senta-te calada, e entra nas trevas, ó filha dos caldeus; porque nunca mais serás chamada de senhora dos reinos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 6, 'Tive muita ira contra meu povo; profanei minha herança, e os entreguei em tuas mãos; [porém] tu não lhes foste misericordiosa, [e até] sobre os velhos puseste teu jugo muito pesado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 7, 'E dizias: Serei senhora para sempre; Até agora não pensaste estas coisas em teu coração, nem te lembraste do fim que elas teriam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 8, 'Agora, pois, ouve isto, ó amante dos prazeres, que habitas tão segura, que dizes em teu coração: Somente eu, e ninguém mais; não ficarei viúva, nem saberei como é perder um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 9, 'Porém ambas estas coisas virão sobre ti, em um momento no mesmo dia: perda de filhos e viuvez; em completa totalidade virão sobre ti, por causa de tuas muitas feitiçarias, por causa da abundância de teus muitos encantamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 10, 'Pois confiaste em tua maldade, [e] disseste: Ninguém me vê.Tua sabedoria e teu conhecimento, esses te fizeram desviar, e disseste em teu coração: Somente eu, e ninguém mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 11, 'Então virá sobre ti um mal do qual não saberás a origem, e destruição cairá sobre ti, a qual não poderás solucionar; porque virá sobre ti de repente [tão] tempestuosa assolação, que não poderás reconhecer [com antecedência] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 12, 'Fica [ainda] com teus encantamentos, e com as tuas muitas feitiçarias, em que trabalhaste desde a tua juventude; para [ver se] talvez ter algum proveito, ou quem sabe provoques algum medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 13, 'Tu te cansaste com tantos conselhos que recebeste; levantem-se, pois, agora, os que observam o céu, os que contemplam as estrelas, os adivinhos das luas novas; e salvem-te daquilo que virá sobre ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 14, 'Eis que eles serão como a palha: o fogo os queimará, não poderão livrar suas vidas do poder das chamas; [essas] não serão brasas para se aquecer, [nem] fogo para [meramente] se sentar perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 47, 15, 'Assim serão para ti aqueles com quem trabalhaste, aqueles com quem fizeste negócios desde a tua juventude. Cada um [deles] andará sem rumo em seu [próprio] caminho; ninguém te salvará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 1, 'Ouvi isto, casa de Jacó, que vos chamais pelo nome de Israel, e saístes das águas de Judá; que jurais pelo nome do SENHOR, e fazeis menção do Deus de Israel, [porém] não em verdade, nem em justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 2, 'E até da santa cidade se chamam; e confiam no Deus de Israel; EU-SOU dos exércitos é o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 3, 'As coisas passadas desde antes anunciei, procederam da minha boca, e eu as declarei publicamente; rapidamente eu as fiz, e elas aconteceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 4, 'Porque eu sabia que tu eras obstinado, e teu pescoço era um nervo de ferro, e tua testa de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 5, 'Por isso eu anunciei a ti com antecedência, [e] te declarei antes que acontecesse, para que não viesses a dizer: Meu ídolo fez estas coisas, ou minha imagem de escultura ou imagem de fundição, [foi ela que] isso ordenou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 6, 'Já tens escutado. Olha bem para tudo isto: por acaso vós não diríeis [que isto é verdade] ? A partir de agora eu te faço ouvir coisas novas, ocultas, e que nunca [antes] soubeste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 7, 'Agora foram criadas, e não antes; e antes de hoje não as ouvistes; para que não viesses a dizer: Eis que eu já as sabia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 8, 'Tu não [as] ouviste, nem [as] soubeste, nem também teu ouvido havia sido aberto antes; porque eu sabia que agirias enganosamente, e que foste chamado de transgressor desde o ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 9, 'Por causa do meu nome adiarei a minha ira, e por louvor a mim me conterei para contigo, para que eu não venha a te eliminar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 10, 'Eis que eu te purifiquei, porém não como a prata; eu te escolhi na fornalha da aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 11, 'Por causa de mim, por causa de mim eu o farei; pois como permitiria [meu nome] ser profanado? E minha glória não darei a outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 12, 'Ouvi-me, ó Jacó, e tu, ó Israel, por mim chamado; eu sou o mesmo; eu sou o primeiro, eu também sou o último.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 13, 'Também minha mão fundou a terra, e minha mão direita estendeu os céus; quando eu os chamo, [logo] eles juntamente aparecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 14, 'Ajuntai-vos, todos vós, e ouvi, quem [há] dentre eles, anunciou estas coisas? O SENHOR o amou, [e] executará sua vontade contra a Babilônia, e seu braço será [contra] os caldeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 15, 'Eu, eu mesmo tenho dito; também eu já o chamei. Eu o farei vir, e ele prosperará [em] seu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 16, 'Achegai-vos a mim, ouvi isto: não falei em oculto desde o princípio; [ao contrário] ,desde o tempo em que aquilo se fez, ali eu estava; e agora o Senhor DEUS me enviou, e seu Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 17, 'Assim diz o SENHOR, teu Redentor, o Santo de Israel: Eu sou o SENHOR teu Deus, que te ensina o que é proveitoso, [e] te guia pelo caminho que deves andar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 18, 'Ah, se tu tivesses me dado ouvidos a meus mandamentos! Então tua paz teria sido como um rio, e tua justiça como as ondas do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 19, 'Também tua semente teria sido como a areia, e os que procedem do teu corpo, como suas pedrinhas, cujo nome nunca seria cortado, nem destruído de minha face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 20, 'Saí da Babilônia, fugi dos caldeus; declarai com voz de júbilo, anunciai, [e] levai isto até o fim da terra; dizei: O SENHOR resgatou a seu servo Jacó!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 21, 'E não tinham sede, [quando] ele os levava pelos desertos; fez correr para eles água da rocha; e quando ele fendia as rochas, águas manavam delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 48, 22, '[Porém] para os perversos não haverá paz,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 1, 'Ouvi-me, terras costeiras, e escutai, vós povos de longe; o SENHOR me chamou desde o ventre, desde as entranhas de minha mãe ele fez menção do meu nome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 2, 'E fez da minha boca como uma espada afiada, com a sombra de sua mão ele me cobriu; e me pôs como uma flecha polida, [e] me guardou em sua aljava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 3, 'E me disse: Tu és meu servo, Israel, por quem serei glorificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 4, 'Porém eu disse: Inutilmente tenho trabalhado; por nada e em vão gastei minhas forças; todavia meu direito está perante o SENHOR, e minha recompensa perante meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 5, 'E agora diz o SENHOR, que me formou desde o ventre para si por servo, que trazer Jacó de volta a si; porém Israel não se deixará ajuntar; contudo, nos olhos do SENHOR serei honrado, e meu Deus será minha força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 6, 'Disse também: É pouco demais que sejas meu servo [apenas] para restaurares as tribos de Jacó e restabeleceres os sobreviventes de Israel; eu também te dei como luz das nações, para seres minha salvação até o limite da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 7, 'Assim diz o SENHOR, o Redentor de Israel, seu Santo, à alma desprezada, ao que a nação abomina, ao servo dos que dominam: Reis o verão e se levantarão, príncipes [também] ; e eles se prostrarão por causa do SENHOR, que é fiel, por causa do Santo de Israel, que te escolheu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 8, 'Assim diz o SENHOR: No tempo do favor eu te ouvi, e no dia da salvação eu te ajudei; e eu te guardarei, e te darei por pacto do povo, para restaurares a terra, para fazer tomar posse das propriedades assoladas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 9, 'Para que tu digas aos presos: Saí; e aos que estão em trevas: Aparecei; eles se alimentarão nos caminhos, e em todos os lugares altos haverá pasto para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 10, 'Nunca terão fome nem sede; nem o calor, nem o sol os afligirá; porque aquele que se compadece deles os guiará, e os levará mansamente a mananciais de águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 11, 'E farei com que todos os meus montes se tornem um caminho; e minhas estradas serão levantadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 12, 'Eis que estes virão de longe; e eis que alguns do norte, e do ocidente, e outros da terra de Sinim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 13, 'Cantai de júbilo, ó céus, e alegra-te tu, ó terra; e vós montes, gritai de alegria; porque o SENHOR consolou a seu povo, e terá compaixão de seus aflitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 14, 'Mas Sião diz: O SENHOR me desamparou; e o Senhor se esqueceu de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 15, 'Pode, por acaso, uma mulher se esquecer do filho que ainda amamenta, de modo que não se compadeça do filho de seu próprio ventre? Ainda que elas se esquecessem, contudo, eu não me esquecerei de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 16, 'Eis que eu te tenho escrito nas minhas palmas de ambas as mãos; teus muros estão continuamente perante mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 17, 'Teus filhos depressa virão; e teus destruidores e teus assoladores sairão de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 18, 'Levanta teus olhos ao redor e olha; todos estes que se ajuntam vêm a ti; [tão certo como] eu vivo, diz o SENHOR, que de todos estes te vestirás, como de ornamento, e vestirás deles ao [teu] redor, como uma noiva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 19, 'Pois [ainda que] teus desertos [sejam] lugares solitários, e tua terra [esteja] destruída, agora te verás apertada de moradores, e os que te consumiram se afastarão para longe de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 20, 'Até mesmo os filhos que nascerem depois de teres perdido os primeiros dirão aos teus ouvidos: Este lugar é muito apertado para mim! Dá-me espaço para que eu possa habitar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 21, 'E dirás em teu coração: Quem a estes me gerou? Pois eu estava sem filhos e solitária; quem, pois, [me] criou a estes? Eis que eu fui deixada sozinha; [e] estes, onde estavam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 22, 'Assim diz o Senhor DEUS: Eis que levantarei minha mão às nações, e erguerei minha bandeira aos povos; então trarão teus filhos nos braços, e tuas filhas serão levadas sobre os ombros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 23, 'E reis serão teus tutores, e suas princesas tuas amas; perante ti se inclinarão com o rosto em terra, e lamberão o pó de teus pés; e saberás que eu sou o SENHOR; aqueles que esperam por mim não serão envergonhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 24, 'Pode, por acaso, se tirar a presa de um guerreiro, ou fazer escapar os presos capturados por um justo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 25, 'Porém assim diz o SENHOR: Sim, os presos serão tirados do valente, e a presa do tirano escapará; porque eu brigarei com os que brigam contigo, e resgatarei teus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 49, 26, 'E darei de comer a teus opressores sua própria carne, e com seu próprio sangue se embriagarão, como com vinho; e todos saberão que eu sou o SENHOR teu Salvador, e teu Redentor, o Poderoso de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 1, 'Assim diz o SENHOR: Onde está a carta de divórcio de vossa mãe, com que eu a mandei embora? Ou a qual dos meus credores foi que eu vos vendi? Eis que por vossas maldades fostes vendidos, e por vossas transgressões vossa mãe foi expulsa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 2, 'Por que razão quando eu vim ninguém apareceu? Chamei, e ninguém respondeu. Por acaso minha mão se encurtou tanto, que já não posso resgatar? Ou não há [mais] poder em mim para livrar? Eis que com minha repreensão faço secar o mar, torno os rios em deserto, até federem seus peixes por não haver água, e morrem de sede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 3, 'Eu visto aos céus de negro, e ponho um saco como sua cobertura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 4, 'O Senhor DEUS me deu língua de instruídos, para que eu saiba falar no tempo devido uma [boa] palavra ao cansado; ele me desperta todas as manhãs, desperta o meu ouvido para que eu ouça como os instruídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 5, 'O Senhor DEUS abriu os meus ouvidos, e não sou rebelde; nem me viro para trás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 6, 'Dei minhas costas aos que [me] feriam, e os lados do meu rosto aos que me arrancavam os pelos; não escondo minha face de humilhações e cuspidas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 7, 'Porque o Senhor DEUS me ajuda; portanto não me envergonho; por isso pus meu rosto como pedra muito dura; porque sei que não serei envergonhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 8, 'Perto está aquele que me justifica; quem se oporá a mim? Compareçamos juntos; quem é meu adversário? Venha até mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 9, 'Eis que o Senhor DEUS me ajuda; quem é que [o que] me condenará? Eis que todos eles tal como vestidos se envelhecerão, [e] a traça os comerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 10, 'Quem há entre vós que tema ao SENHOR, [e] ouça a voz de seu servo? Aquele que andar em trevas, e não tiver luz nenhuma, confie no nome do SENHOR, e dependa de seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 50, 11, 'Eis que todos vós que acendeis fogo, e vos envolveis com chamas, andai entre as labaredas de vosso fogo, e entre as chamas que acendestes; isto recebereis de minha mão, e em tormentos jazereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 1, 'Ouvi-me, vós que seguis a justiça, os que buscais ao SENHOR; olhai para a rocha [de onde] fostes cortados, e para a escavação do poço [de onde] fostes cavados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 2, 'Olhai para Abraão vosso pai, e para Sara que vos gerou; porque, sendo ele sozinho eu o chamei, o abençoei e o multipliquei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 3, 'Pois o SENHOR consolará a Sião; ele consolará a todos os seus lugares desertos, e fará a seu deserto como a Éden, e seu lugar vazio como o jardim do SENHOR; alegria e contentamento se achará nela; agradecimentos e voz de melodia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 4, 'Prestai atenção a mim, povo meu; e minha nação, inclinai teus ouvidos a mim; porque a Lei procederá de mim, e meu porei meu juízo como luz para os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 5, 'Perto está minha justiça, já partiu minha salvação, e meus braços julgarão aos povos; os litorais aguardarão por mim, e por meu braço esperarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 6, 'Levantai vossos olhos aos céus, e olhai para a terra abaixo; porque os céus desaparecerão como fumaça, e a terra se envelhecerá como um vestido; e seus moradores semelhantemente morrerão; porém minha salvação durará para sempre, e minha justiça não será terminará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 7, 'Ouvi-me, vós que conheceis a justiça, vós povo em cujo coração está minha Lei; não temais a humilhação dos homens, nem vos perturbeis por seus insultos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 8, 'Porque a traça os roerá como um vestido; e o verme os comerá com a lã; mas minha justiça durará para sempre, e minha salvação geração após gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 9, 'Desperta-te! Desperta-te! Reveste-te de força, ó braço do SENHOR! Desperta-te como nos dias do passado, [como] nas gerações antigas; por acaso não és tu aquele que cortaste em pedaços a Raabe, que feriste ao dragão marinho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 10, 'Não és tu aquele que secaste o mar, as águas do grande abismo, e que fizeste o caminho das profundezas do mar, para que passassem os redimidos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 11, 'Assim voltarão os regatados do SENHOR, e virão a Sião cantando; e alegria perpétua haverá sobre suas cabeças; júbilo e alegria terão; tristeza e gemido fugirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 12, 'Eu, eu sou aquele que vos consola; quem és tu, para que tenhas medo do homem mortal, ou do filho do homem [que] é como grama,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 13, 'E te esqueças do SENHOR, aquele que te fez, que estendeu os céus e fundou a terra, e temes continuamente o dia todo à fúria do opressor, como se ele estivesse pronto para destruir? Onde está [essa] fúria do opressor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 14, 'O preso logo será solto, e não morrerá na cova, nem seu pão lhe faltará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 15, 'Pois eu sou o SENHOR teu Deus, que divido o mar, e bramam suas ondas. EU-SOU dos exércitos é o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 16, 'E ponho minhas palavras em tua boca, e te cubro com a sombra de minha mão; para plantar os céus, e para fundar a terra, e para dizer a Sião: Tu és meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 17, 'Desperta-te! Desperta-te! Levanta-te, ó Jerusalém, que bebeste da mão do SENHOR o cálice de seu furor; bebeste [e] sugaste os resíduos do cálice do cambaleio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 18, 'De todos os filhos que ela gerou, nenhum há que a guie mansamente; e de todos os filhos que ela criou, nenhum há que a segure pela mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 19, 'Estas duas coisas te aconteceram; quem terá compaixão de ti? Assolação e ruína; fome e espada; por meio de quem te consolarei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 20, 'Os teus filhos desmaiaram, jazem nas entradas de todos os caminhos, como um antílope numa rede; cheios estão do furor do SENHOR, e da repreensão de teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 21, 'Portanto agora ouve isto, ó oprimida e embriagada, mas não de vinho:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 22, 'Assim diz o teu Senhor, o SENHOR, e teu Deus, que defende a causa de seu povo: eis que eu tomo da tua mão o cálice do cambaleio, os resíduos do cálice de meu furor; nunca mais o beberás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 51, 23, 'Porém eu o porei nas mãos dos que afligiram, que dizem à tua alma: Abaixa-te, e passaremos sobre [ti] ; e pões as tuas costas como chão, como caminho aos que passam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 1, 'Desperta-te! Desperta-te! Veste-te de tua força, ó Sião! Veste-te de teus belos vestidos, ó Jerusalém, cidade Santa! Porque nunca mais entrará em ti nem incircunciso nem impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 2, 'Sacode-te do pó, levanta-te, [e] senta-te, ó Jerusalém! Solta-te das ataduras de teu pescoço, ó cativa filha de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 3, 'Porque assim diz o SENHOR: Por nada fostes vendidos, também sem [ser por] dinheiro sereis resgatados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 4, 'Porque assim diz o Senhor DEUS: Meu povo em tempos passados desceu ao Egito para lá peregrinar; e a Assíria sem razão o oprimiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 5, 'E agora, o que tenho [de fazer] aqui?,Diz o SENHOR, Pois meu povo foi tomado sem motivo algum; e os que dominam sobre ele uivam, diz o SENHOR; E meu nome continuamente, durante o dia todo, é blasfemado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 6, 'Por isso meu povo conhecerá o meu nome, por esta causa naquele dia; porque eu mesmo sou o que digo, eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 7, 'Como são agradáveis sobre os montes os pés daquele que dá boas notícias, que anuncia a paz; que fala notícias do bem; que anuncia a salvação; do que diz a Sião: Teu Deus reina!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 8, '[Eis] a voz dos teus vigilantes; eles levantam a voz, juntamente gritam de alegria; porque olho a olho verão quando o SENHOR trazer de volta a Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 9, 'Gritai de alegria, jubilai juntamente, ó lugares abandonados de Jerusalém; porque o SENHOR consolou a seu povo, redimiu a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 10, 'O SENHOR expôs o seu santo braço perante os olhos de todas as nações; e todos os confins da terra verão a salvação de nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 11, 'Retirai-vos! Retirai-vos! Saí daí! Não toqueis em coisa impura! Saí do meio dela! Purificai-vos vós que levais os vasos do SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 12, 'Pois vós não saireis apressadamente, nem ireis fugindo; porque o SENHOR irá adiante de vossa face, o Deus de Israel será vossa retaguarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 13, 'Eis que meu servo agirá prudentemente; ele será exaltado e elevado, e muito sublime.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 14, 'Como muitos se espantaram de ti, de que a aparência dele estava tão desfigurada, mais do que qualquer outro; que seu aspecto já não [parecia] com os filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 52, 15, 'Assim ele salpicará a muitas nações, e sobre ele os reis fecharão suas bocas; porque aquilo que nunca lhes havia sido anunciado, [isso] verão; e aquilo que nunca tinham ouvido, [disso] entenderão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 1, 'Quem creu em nossa pregação? E a quem se manifestou o braço do SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 2, 'Pois foi crescendo como renovo perante ele, e como raiz de terra seca; não tinha boa aparência nem formosura; e quando olhávamos para ele, não havia [nele] boa aparência, para que o desejássemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 3, 'Ele era desprezado e rejeitado entre os homens, era homem de dores, e experiente em enfermidade; ele era como alguém de quem [os outros] escondiam o rosto; era desprezado, e não lhe estimávamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 4, 'Verdadeiramente ele tomou sobre si nossas enfermidades, e nossas dores levou sobre si; e nós o considerávamos como afligido, ferido por Deus, e oprimido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 5, 'Porém ele foi ferido por nossas transgressões, [e] esmagado por nossas perversidades; o castigo que nos traz a paz estava sobre ele, e por suas feridas fomos curados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 6, 'Todos nós andávamos sem rumo como ovelhas; cada um se desviava por seu caminho; porém o SENHOR fez vir sobre ele a perversidade de todos nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 7, 'Ele foi oprimido e afligido, porém não abriu sua boca; tal como cordeiro ele foi levado ao matadouro, e como ovelha muda perante seus tosquiadores, assim ele não abriu sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 8, 'Com opressão e julgamento ele foi removido; e quem falará de sua geração? Porque ele foi cortado da terra dos viventes; pela transgressão do meu povo ele foi ferido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 9, 'E puseram sua sepultura com perversos, e com um rico em sua morte; pois ele nunca fez injustiça, nem houve engano em sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 10, 'Porém agradou ao SENHOR esmagá-lo, fazendo-o ficar enfermo; quando sua alma for posta como expiação do pecado, ele verá semente, [e] prolongará os dias; e o bom prazer do SENHOR prosperará em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 11, 'A [consequência] do trabalho de sua alma ele verá [e] se fartará; com seu conhecimento o meu servo, o justo, justificará a muitos, pois levará sobre si as perversidades deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 53, 12, 'Por isso lhe darei a porção de muitos, e e com os poderosos ele repartirá despojo, pois derramou sua alma na morte, e foi contado com os transgressores; e levou sobre si o pecado de muitos, e intercedeu pelos transgressores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 1, 'Canta alegremente, ó estéril, [que] não geravas; grita de prazer com alegre canto, e jubila tu que não tiveste dores de parto; pois mais são os filhos da solitária do que os filhos da casada, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 2, 'Aumenta o espaço de tua tenda, e as cortinas de tuas habitações sejam estendidas; não o impeças; alonga tuas cordas, e fixa bem tuas estacas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 3, 'Porque transbordarás à direita e à esquerda; e tua semente tomará posse das nações, e farão habitar as cidades assoladas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 4, 'Não temas, pois não serás envergonhada; e não te envergonhes, pois não serás humilhada; ao contrário, te esquecerás da vergonha da tua juventude, e não te lembrarás mais da desonra de tua viuvez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 5, 'Porque teu marido é o Criador; EU-SOU dos exércitos é o seu nome; e o Santo de Israel é o teu Redentor; ele será chamado: o Deus de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 6, 'Pois o SENHOR te chamou como mulher abandonada, e triste de espírito; como uma mulher da juventude que havia sido rejeitada, diz o teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 7, 'Por um curto momento te deixei; porém com grandes misericórdias te recolherei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 8, 'Num acesso de ira escondi minha face de ti por um momento; porém com bondade eterna terei compaixão de ti, diz o SENHOR teu Redentor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 9, 'Porque isto será para mim [como] as águas de Noé, quando jurei que as águas de Noé não mais passaria sobre a terra; assim jurei, que não me irarei contra ti, nem te repreenderei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 10, 'Porque montes se removerão e morros se retirarão, porém minha bondade não se removerá de ti, nem o pacto de minha paz se retirará, diz o SENHOR, que tem compaixão de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 11, 'Tu, oprimida, afligida por tempestade, [e] desconsolada: eis que eu porei tuas pedras com ornamentos, e te fundarei sobre safiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 12, 'E farei de rubis as tuas torres; e tuas portas de carbúnculos, e todos os teus limites com pedras preciosas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 13, 'E todos os teus filhos serão ensinados pelo SENHOR; e a paz de teus filhos será abundante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 14, 'Com justiça serás firmada; afasta-te da opressão, porque já não temerás; assim como também do assombro, porque este não se aproximará de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 15, 'Se alguém lutar [contra ti] ,não será por mim; quem lutar contra ti cairá por causa de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 16, 'Eis que fui eu que criei ao ferreiro que assopra as brasas no fogo, e que produz a ferramenta para sua obra; também fui eu que criei ao destruidor, para causar ruína.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 54, 17, 'Nenhuma ferramenta preparada contra ti terá sucesso; e toda língua que se levantar contra ti em juízo, tu a condenarás; esta é a herança dos servos do SENHOR; e a justiça deles [provém] de mim, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 1, 'Ó todos vós que tendes sede, vinde às águas; e vós que não tendes dinheiro, vinde, comprai, e comei; vinde, comprai, sem dinheiro e sem preço, vinho e leite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 2, 'Por que gastais dinheiro naquilo que não é pão, e vosso trabalho naquilo que não pode trazer satisfação? Ouvi-me com atenção, e comei o que é bom, e vossa alma se deleite com a gordura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 3, 'Inclinai vossos ouvidos, e vinde a mim; ouvi, e vossa alma viverá; porque convosco farei um pacto eterno, [tal como] as firmes bondades prometidas a Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 4, 'Eis que eu o dei [para ser] testemunha aos povos, [como] príncipe e governante dos povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 5, 'Eis que chamarás a uma nação que não conheceste, e uma nação que nunca te conheceu correrá para ti, por causa do SENHOR teu Deus, o Santo de Israel; porque ele te glorificou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 6, 'Buscai ao SENHOR enquanto se pode achar; invocai-o enquanto ele está perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 7, 'Que o perverso deixe seu caminho, e o homem maligno [deixe] seus pensamentos, e converta ao SENHOR; então dele terá compaixão; [converta] ao nosso Deus, porque ele grandemente perdoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 8, 'Pois meus pensamentos não são vossos pensamentos, nem vossos caminhos são meus caminhos, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 9, 'Porque [tal como] os céus são mais altos que a terra, assim também meus caminhos são mais altos que vossos caminhos, e meus pensamentos [mais altos] que vossos pensamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 10, 'Porque tal como a chuva e a neve desce dos céus, e para lá não volta, mas rega a terra, e a faz produzir, brotar, e dar semente ao semeador, e pão ao que come;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 11, 'Assim também será minha palavra, que não voltará a mim vazia; ao contrário, ela fará o que me agrada, e cumprirá aquilo para que a enviei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 12, 'Porque com alegria saireis, e em paz sereis guiados; os montes e os morros cantarão de alegria perante vossa presença, e todas as árvores do campo baterão palmas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 55, 13, 'Em lugar do espinheiro crescerá o cipreste, e em lugar da urtiga crescerá a murta; e isso será para o SENHOR como um nome, como um sinal eterno, que nunca se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 1, 'Assim diz o SENHOR: Guardai o que é justo, e praticai a justiça; porque minha salvação já está perto de vir, e minha justiça de se manifestar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 2, 'Bem-aventurado o homem que fizer isto, e o filho do homem que permanece nisto; que se guarda para não profanar o sábado, e guarda sua mão para não cometer algum mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 3, 'E não fale o filho do estrangeiro, que tiver se ligado ao SENHOR, dizendo: Certamente o SENHOR me excluiu de seu povo; nem fale o eunuco: Eis que sou uma árvore seca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 4, 'Porque assim diz o SENHOR: Aos eunucos, que guardam os meus sábados, e escolhe aquilo em que me agrado, e permanecem em meu pacto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 5, 'Eu também lhes darei em minha casa, e dentro de meus muros, lugar e nome, melhor que o de filhos e filhas; darei um nome eterno a cada um deles, que nunca se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 6, 'E aos filhos dos estrangeiros, que se ligarem ao SENHOR, para o servirem, e para amarem o nome do SENHOR, e para serem seus servos, todos os que guardarem o sábado, não o profanando, e os que permanecerem em meu pacto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 7, 'Eu os levarei ao meu santo monte, e lhes farei se alegrarem em minha casa de oração; seus holocaustos e seus sacrifícios serão aceitos em meu altar; porque minha casa será chamada “Casa de oração para todos os povos”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 8, '[Assim] diz o Senhor DEUS, que junta os dispersos de Israel: Ainda [outros] mais lhe ajuntarei, além dos que já lhe foram ajuntados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 9, 'Todos vós, animais do campo, vinde comer!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 10, 'Todos os seus vigilantes são cegos, nada sabem; todos são cães mudos, não podem latir; andam adormecidos, estão deitados, e amam cochilar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 11, 'E estes são cães gulosos, não conseguem se satisfazer; e eles são pastores que nada sabem entender; todos eles se viram a seus caminhos, cada um à sua ganância, [cada um] por si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 56, 12, '[Eles dizem] : Vinde, trarei vinho, e nos encheremos de bebida alcoólica; e o dia de amanhã será como hoje, e muito melhor!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 1, 'O justo perece, e ninguém há que pense nisso em seu coração; e os bons são levados, sem que ninguém dê atenção, que o justo é levado de diante do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 2, 'Ele entrará [em] paz; descansarão em suas camas aqueles que vivem corretamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 3, 'Mas chegai-vos aqui, filhos da adivinha, descendência adúltera, e que cometeis pecados sexuais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 4, 'De quem fazeis piadas de escárnio? Contra quem alargais a boca, e colocais a língua para fora? Por acaso não sois filhos da transgressão, [e] descendentes da falsidade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 5, '[Não sois] vós, que vos inflamais com os ídolos abaixo de toda árvore verde, [e] sacrificais os filhos nos vales, abaixo das fendas dos penhascos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 6, 'Nas pedras lisas dos ribeiros está tua parte; estas, estas são aquilo que te pertence; a estas também derramas ofertas de líquidos, [e] lhe apresenta ofertas. Por acaso ficaria eu contente com estas coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 7, 'Sobre altos e elevados montes pões tua cama; e a eles sobes para oferecer sacrifícios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 8, 'E debaixo das portas e dos umbrais pões teus memoriais; porque a não a mim, mas a outros tu [te] descobres, e sobes, alargas tua cama, e fazes [pacto] com eles; amas a cama deles, a nudez que tu vês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 9, 'E foste ao rei com óleo, e multiplicaste teus perfumes; e enviaste teus embaixadores para longe, e desceste até o Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 10, 'Em tua longa viagem te cansaste, [porém] não disseste: Não tenho mais esperança. Achaste força em tua mão, por isso não desanimaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 11, 'Mas de quem tiveste receio e temeste? Por que mentiste, e não te lembraste de mim, nem pensaste em mim em teu coração? Por eu ter me calado desde muito tempo, [agora] não me temes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 12, 'Eu declararei abertamente a tua justiça, e tuas obras; mas elas não te trarão proveito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 13, 'Quando tu vieres a clamar, que os ídolos que juntaste te livrem; porém o vento levará a todos eles, e um sopro os arrebatará; mas aquele que confia em mim herdará a terra, e tomará posse do meu santo monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 14, 'E será dito: Aplanai! Aplanai! Preparai o caminho! Tirai os tropeços do caminho do meu povo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 15, 'Porque assim diz o Alto e Sublime, que habita na eternidade, e cujo nome é santo: Na altura e no lugar santo habito; e também com o contrito e abatido espírito, para vivificar o espírito dos abatidos, e para vivificar o coração dos contritos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 16, 'Pois não brigarei para sempre, nem ficarei continuamente indignado; pois perderia todas as forças diante de mim o espírito, as almas que eu criei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 17, 'Pela maldade de sua cobiça eu me indignei, e o feri; eu me escondi, e me indignei; porém ele se rebelou seguindo o caminho de seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 18, 'Tenho visto seus caminhos; porém eu o sararei, e o guiarei, e voltarei a dar consolo, a ele a os que por ele lamentam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 19, 'Eu crio os frutos dos lábios; paz, paz para os que estão longe e para os que estão perto,diz o SENHOR, e eu os sararei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 20, 'Mas os perversos são como o mar bravo, que não pode se aquietar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 57, 21, 'Os perversos, (diz meu Deus), não tem paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 1, 'Clama em alta voz, não te retenhas; levanta tua voz como trombeta; e anuncia a meu povo sua transgressão, e à casa de Jacó seus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 2, 'Porém eles me buscam diariamente, e tem prazer em conhecer os meus caminhos, como [se fossem] um povo que pratica justiça, e não abandona o juízo de seu Deus; perguntam-me pelos juízos de justiça, e tem prazer em se achegarem a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 3, '[Eles dizem:] Por que nós jejuamos, e tu não dás atenção a isso? [Por que] afligimos nossas almas, e tu não o reconheces?Eis que nos dia em que jejuais, continuais a buscar [apenas] aquilo que vos agrada, e sobrecarregais todos os que trabalham para vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 4, 'Eis que jejuais para brigas e discussões, e para dardes socos de maldade; não jejueis como [fazeis] hoje, para que vossa vossa voz seja ouvida no alto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 5, 'Seria este o jejum que eu escolheria, que o homem um dia aflija sua alma, incline sua cabeça como o junco, e estenda debaixo [de si] saco e cinza? Chamarias tu a isto jejum e dia agradável ao SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 6, 'Por acaso não é este o jejum que eu escolheria: que soltes os nós de perversidade, que desfaças as amarras do jugo, e que libertes aos oprimidos, e quebres todo jugo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 7, 'Por acaso não é [também] que repartas teu pão com o faminto, e aos pobres desamparados recolhas em casa, [e] vendo ao nu, que o cubras, e não te escondas de tua carne?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 8, '[Quando fizeres isto] , então tua luz surgirá como o amanhecer, e tua cura logo chegará; e tua justiça irá adiante de ti; a glória do SENHOR será tua retaguarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 9, 'Então clamarás, e o SENHOR [te] responderá; gritarás, e dirá: Eis-me aqui; se tirares do meio de ti o jugo, o estender de dedo, e o falar perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 10, 'E se abrires tua alma ao faminto, e fartares à alma afligida; então tua luz nascerá das trevas, e tua escuridão será como o meio-dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 11, 'E o SENHOR te guiará continuamente, fartará a tua alma [mesmo] em grandes secas, e fortalecerá teus ossos; e tu serás como um jardim regado, como um manancial de águas, cujas águas nunca faltam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 12, 'E os que de ti [procederem] edificarão os lugares antes arruinados, e levantarás os fundamentos das gerações [passadas] ; e te chamarão reparador das coisas que se romperam, e restaurador das ruas para se morar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 13, 'Se quanto ao sábado recusares fazer tua vontade no meu santo dia, e chamares ao sábado de agradável, santificado ao SENHOR, e glorioso, e tu o honrares, não seguindo teus caminhos, [nem] buscando tua própria vontade, falando [o que não se deve] ,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 58, 14, 'Então tu te agradarás no SENHOR, e te farei montar sobre as alturas da terra; e te darei sustento com a herança de teu pai Jacó; porque [assim] a boca do SENHOR falou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 1, 'Eis que a mão do SENHOR não está encolhida, para que não possa salvar; nem seu ouvido surdo, para não poder ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 2, 'Porém vossas perversidades fazem separação entre vós e vosso Deus; e vossos pecados encobrem o rosto dele de vós, para que não ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 3, 'Porque vossas mãos estão contaminadas de sangue, e vossos dedos de maldade; vossos lábios falam falsidade, vossa língua pronuncia perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 4, 'Ninguém há que clame pela justiça, nem ninguém que defenda causa em juízo por meio da verdade; confiam naquilo que é inútil, e falam mentiras; são causadores de opressão, e geram injustiça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 5, 'Chocam ovos de serpente, e tecem teias de aranha; quem comer de seus ovos morrerá, e sairá uma cobra venenosa se forem pisados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 6, 'Suas teias não servem para vestimentas, nem poderão se cobrir com suas obras; suas obras são obras de injustiça, e atos de violência há em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 7, 'Seus pés correm para o mal, e se apressam para derramarem sangue inocente; seus pensamentos são pensamentos de injustiça, destruição e ruína há em suas estradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 8, 'O caminho da paz eles não conhecem, nem há justiça em seus percursos; entortam suas veredas para si mesmos; todo aquele que anda por elas não experimentará paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 9, 'Por isso o juízo está longe de nós, nem a justiça nos alcança; esperamos luz , [porém] eis que há [somente] trevas; [esperamos] brilho, [porém] andamos às escuras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 10, 'Apalpamos as paredes como cegos, e como se não tivéssemos olhos andamos apalpando; tropeçamos ao meio-dia como se fosse noite; entre os fortes estamos como mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 11, 'Todos nós bramamos como ursos, e continuamente gememos como pombas; esperamos pela justiça, e nada [acontece] ; [esperamos] pela salvação, [porem] ela está longe de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 12, 'Pois nossas transgressões se multiplicaram diante de ti, e nossos pecados dão testemunho contra nós; pois nossas transgressões estão conosco, e conhecemos nossas perversidades,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 13, '[Tais como] : transgredir e mentir contra o SENHOR, e se desviar de seguir a nosso Deus; falar de opressão e rebelião, conceber e falar palavras de falsidade do coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 14, 'Por isso que o direito retrocedeu, e a justiça ficou de longe; pois a verdade tropeçou na praça, e a correta decisão não pode entrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 15, 'E a verdade se perde, e quem se desvia do mal corre o risco de ser saqueado; e o SENHOR o viu, pareceu mal em seus olhos, por não haver justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 16, 'E vendo que ninguém havia, maravilhou-se de que não houvesse intercessor algum; por isso seu próprio braço lhe trouxe a salvação, e sua própria justiça o susteve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 17, 'Pois ele se vestu de justiça como uma armadura, e [pôs] o capacete da salvação em sua cabeça; e vestiu-se de roupas de vingança [como] vestimenta, e cobriu-se de selo como uma capa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 18, 'Ele [lhes] retribuirá conforme [suas] obras: furor a seus adversários, pagamento a seus inimigos; aos litorais ele pagará de volta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 19, 'Então temerão o nome do SENHOR desde o ocidente, e sua glória desde o oriente; pois ele vem como uma correnteza impetuosa, empurrada pelo sopro do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 20, 'E um Redentor virá a Sião, para aqueles que se arrependerem de [sua] transgressão em Jacó, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 59, 21, 'Quanto a mim, este é meu pacto com eles,diz o SENHOR; meu Espírito que está sobre ti, e minhas palavras que pus em tua boca, não se afastarão de tua boca nem da boca de teus descendentes, nem da boca dos descendentes de teus descendentes, diz o SENHOR, desde agora e para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 1, 'Levanta-te! Brilha! Porque já chegou a tua luz; e a glória do SENHOR já está raiando sobre ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 2, 'Porque eis que as trevas cobrirão a terra, e a escuridão aos povos; porém sobre ti o SENHOR virá raiando, e sua glória será vista sobre ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 3, 'E as nações virão à tua luz, e os reis ao brilho que raiou a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 4, 'Levanta teus olhos ao redor, e vê; todos estes se ajuntaram, [e] vem a ti; teus filhos virão de longe, e tuas filhas serão criadas ao teu lado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 5, 'Então verás, e te alegrarás; teu coração palpitará e se encherá de alegria, porque a abundância do mar a ti se voltará, as riquezas das nações a ti chegarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 6, 'Multidão de camelos te cobrirá; dromedários de Midiã e Efá, todos virão de Sabá; trarão ouro e incenso, e declararão louvores ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 7, 'Todas as ovelhas de Quedar se ajuntarão a ti; os carneiros de Nebaiote te servirão; com agrado subirão ao meu altar, e eu glorificarei a casa de minha glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 8, 'Quem são estes que vêm voando como nuvens, e como pombas às suas janelas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 9, 'Pois as ilhas me esperarão, e primeiro os navios de Társis, para trazer teus filhos de longe, sua prata e seu ouro com eles; para o nome do SENHOR teu Deus, e para o Santo de Israel, porque ele te glorificou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 10, 'E filhos de estrangeiros edificarão teus muros, e seus reis te servirão; porque em minha ira eu te feri, porém em meu favor tive misericórdia de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 11, 'E tuas portas estarão continuamente abertas, nem de dia nem de noite se fecharão; para que tragam a ti as riquezas das nações, e seus reis [a ti] sejam trazidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 12, 'Pois a nação e reino que não te servirem perecerão; e tais nações serão assoladas por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 13, 'A glória do Líbano virá a ti, a faia, o pinheiro, e o cipreste juntamente, para ornamentarem o lugar do meu santuário, e glorificarei o lugar de meus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 14, 'Também virão a ti inclinados os filhos dos que te oprimiram, e se prostrarão às pisadas de teus pés todos os que blasfemaram de ti; e te chamarão a cidade do SENHOR, a Sião do Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 15, 'Em vez de abandonada e odiada, [de tal modo] que ninguém passava [por ti] ,eu farei de ti uma excelência eterna, alegria de geração após geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 16, 'E mamarás o leite das nações, e mamarás os peitos dos reis; e saberás que eu sou o SENHOR, teu Salvador e teu Redentor, o Poderoso de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 17, 'Em vez de bronze trarei ouro, e em vez de ferro trarei prata, e em vez de madeira bronze, e em vez de pedras ferro; e farei pacíficos teus oficiais, e justos aqueles que cobram de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 18, 'Nunca mais se ouvirá falar de violência em tua terra; [nem] ruína, nem destruição dentro de tuas fronteiras; em vez disso, a teus muros chamarás Salvação, e a tuas portas Louvor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 19, 'Nunca mais o sol te servirá para luz do dia, nem com [seu] brilho a lua te iluminará; mas o SENHOR será tua luz eterna, e teu Deus o teu ornamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 20, 'Nunca mais o teu sol irá se por, nem tua lua minguará; porque o SENHOR será tua luz eterna, e os dias de teu luto se acabarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 21, 'E todos os de teu povo serão justos; para sempre terão posse da terra; serão renovo de minha plantação, obra de minhas mãos, para que eu seja glorificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 60, 22, 'O menor será mil, e o de menor tamanho será um povo forte; eu, o SENHOR, o farei depressa em seu [devido] tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 1, 'O Espírito do Senhor DEUS está sobre mim; pois o SENHOR me ungiu, para dar boas novas aos mansos; ele me enviou para sarar aos feridos de coração, para anunciar liberdade aos cativos, e libertação aos prisioneiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 2, 'Para anunciar o ano do favor do SENHOR, e o dia da vingança de nosso Deus; para consolar todos os tristes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 3, 'Para ordenar aos tristes de Sião, que lhes seja dado ornamento no lugar de cinza, óleo de alegria no lugar de tristeza, vestes de louvor no lugar de espírito angustiado; para que sejam chamados de carvalhos da justiça, plantação do SENHOR; para que ele seja glorificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 4, 'E edificarão os lugares arruinados desde os tempos antigos, restaurarão os desde antes destruídos, e renovarão as cidades arruinadas, destruídas desde muitas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 5, 'E estrangeiros apascentarão vossos rebanhos, e filhos de outras nações serão vossos lavradores e vossos trabalhadores nas vinhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 6, 'Porém vós sereis chamados sacerdotes do SENHOR; chamarão a vós de trabalhadores a serviço de nosso Deus; comereis dos bens das nações, e da riqueza deles vós vos orgulhareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 7, 'Em vez de vossa vergonha, [tereis] porção dobrada; e [em vez] de humilhação, terão alegria sobre sua parte; pois em sua terra terão posse do dobro, [e] terão alegria eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 8, 'Porque eu, o SENHOR, amo a justiça, e odeio o roubo com sacrifício de queima; e farei que sua obra seja em verdade, e farei um pacto eterno com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 9, 'E sua descendência será conhecida entre as nações, e seus descendentes em meio aos povos; todos quantos os virem, os reconhecerão, que são descendência abençoada pelo SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 10, 'Eu estou muito jubilante no SENHOR, minha alma se alegra em meu Deus; porque ele me vestiu de roupas de salvação; ele me cobriu com a capa da justiça, tal como o noivo [quando] se veste da roupa sacerdotal, e como a noiva se enfeita com suas joias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 61, 11, 'Porque tal como a terra produz seus renovos, e como o jardim faz brotar o que nele se semeia, assim também o Senhor DEUS fará brotar justiça e louvor diante de todas as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 1, 'Por Sião eu não me calarei, e por Jerusalém não me aquietarei, enquanto sua justiça não sair como um brilho, e sua salvação como uma tocha acesa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 2, 'E as nações verão tua justiça, e todos os reis [verão] tua glória; e te chamarão por um novo nome, que a boca do SENHOR determinará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 3, 'E serás coroa de glória na mão do SENHOR, e diadema real na mão de teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 4, 'Nunca mais te chamarão de abandonada, nem se referirão mais a tua terra como assolada; mas sim te chamarão de: “Nela Está Meu Prazer”, e à tua terra de “A Casada”, porque o SENHOR se agrade de ti, e tua terra se casará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 5, 'Porque [tal como] o rapaz se casa com a virgem, [assim também] teus filhos se casarão contigo; e [como] o noivo se alegra da noiva, [assim] o teu Deus se alegrará de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 6, 'Jerusalém, obre os teus muros eu pus guardas, que o dia todo e a noite toda continuamente não se calarão; vós que fazeis menção do SENHOR, não haja silêncio em vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 7, 'Nem deis descanso a ele, até que ele estabeleça, até que ele ponha a Jerusalém como louvor na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 8, 'O SENHOR jurou por sua mão direita e pelo seu forte braço: Nunca mais darei teu trigo [como] comida a teus inimigos, nem estrangeiros beberão teu suco da uva em que trabalhaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 9, 'Mas sim aqueles que o ajuntarem o comerão, e louvarão ao SENHOR; e os que o colherem beberão nos pátios do meu santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 10, 'Passai! Passai pelas portas! Preparai o caminho ao povo! Aplanai! Aplanai a estrada, limpai [-a] das pedras! Levantai uma bandeira aos povos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 11, 'Eis que o SENHOR fez ouvir até a extremidade da terra: Dizei à filha de Sião: eis que tua salvação está vindo; eis que [traz] sua recompensa consigo, e seu pagamento [vem] diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 62, 12, 'E os chamarão de povo santo, redimidos do SENHOR; e tu serás chamada “A Procurada, a Cidade Não Desemparada”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 1, 'Quem é este, que vem de Edom, de Bozra, com vestes salpicadas de vermelho, este ornado em sua vestimenta, que marcha com grande força? Eu, o que falo em justiça, poderoso para salvar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 2, 'Por que tu estás de roupa vermelha, e tuas vestes como de alguém que pisa em uma prensa de uvas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 3, 'Eu sozinho pisei na prensa de uvas, e ninguém dos povos houve comigo; e os pisei em minha ira, e os esmaguei em meu furor; e o sangue deles salpicou sobre minhas roupas, e sujei toda a minha roupa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 4, 'Porque o dia da vingança estava em meu coração; e o ano de meus redimidos havia chegado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 5, 'E olhei, e não havia quem [me] ajudasse; e me espantei de que não houvesse quem [me] apoiasse; por isso meu braço me trouxe a salvação, e meu furor me apoiou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 6, 'E atropelei os povos em minha ira, e os embebedei em meu furor; e fiz descer o sangue deles até a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 7, 'Farei menção das bondades do SENHOR, [e] dos louvores ao SENHOR, conforme tudo quanto o SENHOR fez para nós; e do grande bem à casa de Israel, que ele tem lhes concedido segundo suas misericórdias, e segundo a abundância de suas bondades;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 8, 'Pois ele dizia: Certamente eles são meu povo, são filhos que não mentirão; assim ele se tornou o Salvador deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 9, 'Em toda a angústia deles, ele [também] se angustiou, e o anjo de sua presença os salvou; por seu amor e por sua piedade ele os redimiu; e os tomou, e os carregou [em] todos os dias antigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 10, 'Porém eles foram rebeldes, e entristeceram seu Espírito Santo; por isso ele se tornou inimigo deles, [e] ele mesmo lutou contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 11, 'Contudo ele se lembrou dos dias antigos, de Moisés, [e] de seu povo. Onde está aquele que os fez subir do mar com os pastores de seu rebanho? Onde está aquele que punha no meio deles seu Espírito Santo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 12, '[Onde está] aquele que fez seu glorioso braço andar à direita de Moisés, que dividiu as águas perante a presença deles, para fazer seu nome eterno;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 13, 'Que os guiou pelos abismos como cavalo no deserto, [de tal modo que] nunca tropeçaram?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 14, 'Tal como um animal que desce aos vales, o Espírito do SENHOR lhes deu descanso; assim guiaste a teu povo, para fazeres teu nome ser glorioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 15, 'Olha desde os céus, e vê desde tua santa e gloriosa habitação; onde está teu zelo e tuas forças? A comoção dos sentimentos de teu interior e de tuas misericórdias se retiveram para comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 16, 'Porém tu és nosso Pai, porque Abraão não sabe de nós, nem Israel nos conhece. Tu, SENHOR, és nosso Pai; desde os tempos antigos o teu nome é Nosso Redentor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 17, 'Por que, ó SENHOR, tu nos fazes andar fora de teus caminhos? Por que endureces nosso coração para que não tenhamos temor a ti? Volta, por favor a teus servos, às tribos de tua herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 18, 'Por um pouco de tempo teu santo povo [a] possuiu; nossos adversários pisaram teu santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 63, 19, 'Nós nos tornamos [como aqueles] de quem nunca dominaste, [semelhantes] aos que nunca foram chamados pelo teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 1, 'Ah, se tu rompesses os céus, [e] descesses, os montes se tremeriam de diante de tua presença,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 2, 'Tal como o fogo acende a madeira, [e] o fogo faz ferver as águas; para [assim] fazeres notório o teu nome a teus adversários, [de modo que] as nações tremessem de tua presença!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 3, '[Como] quando fazias coisas temíveis, as quais nunca esperávamos; quando tu descias, [e] os montes se tremiam diante de tua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 4, 'Nem desde os tempos antigos se ouviu, nem com os ouvidos se percebeu, nem olho viu outro Deus além de ti, que age [em favor] daquele que nele espera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 5, 'Tu foste ao encontro do alegre, e do que pratica justiça, [e] aos que se lembram de ti em teus caminhos. Eis que te enfureceste porque pecamos por muito tempo. Seremos salvos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 6, 'Porém todos nós somos como um imundo, e todas as nossas justiças são como roupas contaminadas; e todos nós caímos como uma folha, e nossas culpas nos levam como o vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 7, 'E ninguém há que invoque a teu nome, que se desperte para se apegar a ti; pois tu escondeste teu rosto de nós, e nos consumiste por nossas perversidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 8, 'Porém agora, SENHOR, tu és nosso Pai; nós somos barro, e tu és nosso oleiro; e todos nós somos obra de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 9, 'Não te enfureças tanto, SENHOR, nem te lembres da [nossa] perversidade para sempre; vê, olha agora, [que] todos nós somos teu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 10, 'Tuas santas cidades se tornaram um deserto; Sião se tornou um deserto; Jerusalém está assolada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 11, 'Nossa santa e nossa gloriosa casa, em que nossos pais te louvavam, foi queimada a fogo; e todas as coisas com que nos agradávamos se tornaram ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 64, 12, 'Será que continuarás a te conter sobre estas coisas, SENHOR? Continuarás quieto, e nos oprimindo tanto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 1, 'Fui buscado por aqueles que não perguntavam [por mim] ; fui achado por aqueles que não me buscavam; a uma nação que não se chamava pelo meu nome eu disse: Eis-me aqui! Eis-me aqui!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 2, 'Estendi minhas mãos o dia todo a um povo rebelde, que anda por um caminho que não é bom, seguindo seus próprios pensamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 3, 'Povo que me irrita perante mim continuamente, sacrificando em jardins, e queimando incenso sobre tijolos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 4, 'Sentando-se junto às sepulturas, e passando as noites em lugares secretos; comendo carne de porco, e [tendo] caldo de coisas abomináveis em suas vasilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 5, 'E dizem: Fica onde estás, e não te aproximes de de mim; pois sou mais santo do que tu; Estes são fumaça em minhas narinas, e fogo que arde o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 6, 'Eis que está escrito diante de mim: Não me calarei; mas eu pagarei, e lhes pagarei diretamente e por completo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 7, '[Por] vossas perversidades e juntamente [pelas] perversidades de vossos pais,diz o SENHOR, que com incensos perfumaram nos montes, e me provocaram nos morros; por isso eu lhes medirei de volta por completo o pagamento de suas obras anteriores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 8, 'Assim diz o SENHOR: Tal como quando se acha suco num cacho de uvas, dizem: Não o desperdices, pois há proveito nele; assim eu farei por meus servos; não destruirei a todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 9, 'Mas produzirei descendência de Jacó, e de Judá um herdeiro, que seja dono de meus montes; e meus escolhidos tomarão posse [da terra] ,e meus servos ali habitarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 10, 'E Sarom servirá de pasto de ovelhas, e o vale de Acor como lugar de repouso de gado, para o meu povo, que me buscou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 11, 'Porém a vós, que vos afastais do SENHOR, vós que esqueceis do meu santo monte, que preparais mesa para [o ídolo da] sorte, e que misturais bebida para [o ídolo do] destino;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 12, 'Eu vos destinarei à espada, e todos vós encurvareis à matança; pois eu chamei, e vós não respondestes; falei, e não ouvistes; mas fizestes o que era mal aos meus olhos, e escolhestes aquilo de que não me agrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 13, 'Por isso assim diz o Senhor DEUS: Eis que meus servos comerão, porém vós passareis fome; eis que meus servos beberão, porém vós tereis sede; eis que meus servos se alegrarão, porém vós vos envergonhareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 14, 'Eis que meus servos cantarão de coração contente, porém vós gritareis de tristeza do coração; e uivareis pela angústia de espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 15, 'E deixarei vosso nome a meus eleitos como maldição; e o Senhor DEUS te matará; porém ele chamará aos seus servos por outro nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 16, 'Quem se bendisser na terra, se bendirá no Deus da verdade; e quem jurar na terra, jurará pelo Deus da verdade; porque serão esquecidas as angústias passadas, e porque elas estarão encobertas de diante de meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 17, 'Porque eis que eu crio novos céus e nova terra; e não haverá[mais ] lembrança das coisas passadas, nem mais virão à mente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 18, 'Porém vós ficai contentes e alegrai-vos para sempre [naquilo] que eu crio; porque eis que crio a Jerusalém uma alegria, e a seu povo um contentamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 19, 'E me alegrarei de Jerusalém, e estarei muito contente com meu povo; e nunca mais se ouvirá nela voz de choro, nem voz de clamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 20, 'Não haverá mais ali bebês de [poucos] dias, nem velho que não cumpra seus dias; porque o jovem morrerá aos cem anos, porém o pecador de cem anos de idade será amaldiçoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 21, 'E edificarão casas, e [as] habitarão; e plantarão vinhas, e comerão o fruto delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 22, 'Eles não edificarão para que outros habitem, nem plantarão para que outros comam; porque os dias de meu povo serão como os dias das árvores, e meus escolhidos usarão das obras de suas mãos até a velhice.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 23, 'Não trabalharão em vão, nem terão filhos para a aflição; porque são a semente dos benditos do SENHOR, e seus descendentes com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 24, 'E será que, antes que clamem, eu responderei; enquanto ainda estiverem falando, eu ouvirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 65, 25, 'O lobo e o cordeiro ambos se alimentarão juntos, e o leão comerá palha como o boi, e pó será a comida da serpente; nenhum mal nem dano farão em todo o meu santo monte,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 1, 'Assim diz o SENHOR: Os céus são meu trono, e a terra o escabelo dos meus pés. Qual seria a casa que vós edificaríeis para mim? E qual seria o lugar de meu descanso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 2, 'Pois minha mão fez todas estas coisas, e todas estas coisas passaram a existir,diz o SENHOR; mas para tal eu olharei: aquele que é pobre e abatido de espírito, e treme por minha palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 3, 'Quem mata boi fere de morte a um homem; quem sacrifica cordeiro degola a um cão; quem apresenta oferta, [oferece] sangue de proco; quem oferece incenso adora a um ídolo; também estes escolhem seus [próprios] caminhos, e sua alma tem prazer em suas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 4, 'Eu, então, escolherei a punição para eles, e farei vir sobre eles os seus temores; pois clamei, mas ninguém respondeu; falei, mas não escutaram; ao invés disso fizeram o que era mal aos meus olhos, e escolheram aquilo que não me agrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 5, 'Ouvi a palavra do SENHOR, vós que tremeis por sua palavra; vossos irmãos, que vos odeiam, e vos expulsaram para longe por causa do meu nome, dizem: Que o SENHOR seja glorificado, para que vejamos vossa alegria; eles, porém, serão envergonhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 6, 'Haverá uma voz de grande ruído, uma voz do Templo: é a voz do SENHOR, que dá pagamento a seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 7, 'Antes que estivesse em trabalho de parto, ela já deu à luz; antes que viessem as dores, ela já fez sair de si um filho macho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 8, 'Quem [jamais] ouviu tal coisa? Quem viu coisa semelhante? Poderia uma terra gerar filho em um só dia? Nasceria uma nação de uma só vez? Mas logo que Sião esteve de parto, já teve o nascimento de seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 9, 'Por acaso não iniciaria eu o nascimento e não geraria?,diz o SENHOR, Geraria eu, e fecharia [o ventre materno] ?, diz o teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 10, 'Alegrai-vos com Jerusalém, e enchei-vos de alegria por causa dela, todos vós que a amais; alegrai-vos muito com ela, todos vós que chorastes por ela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 11, 'Para que mameis e vos sacieis dos consoladores seios dela; para que sugueis e vos deleiteis com a abundância de sua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 12, 'Porque assim diz o SENHOR: Eis que estenderei sobre ela a paz como um rio, e a glória das nações como um ribeiro que transborda; então mamareis; sereis levados ao colo, e sobre os joelhos vos afagarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 13, 'Tal como alguém a quem sua mãe consola, assim também eu vos consolarei; e em Jerusalém sereis consolados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 14, 'E vereis; então vossos corações se alegrarão, e vossos ossos se avivarão como a erva que brota. E a mão do do SENHOR será conhecida pelos seu servos, e se enfurecerá contra seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 15, 'Porque eis que o SENHOR virá com fogo, e suas carruagens como um redemoinho de vento; para transformar sua ira em furor, e sua repreensão em chamas de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 16, 'Porque com fogo e com sua espada o SENHOR julgará toda carne; e os mortos pelo SENHOR serão muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 17, 'Os que se consagram e se purificam nos jardins para seguirem aquele que está no meio [deles] ; os que comem carne de porco, abominações, e ratos, juntamente serão consumidos, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 18, 'Porque eu [conheço] suas obras e seus pensamentos. [O tempo] vem, em que juntarei todas as nações e línguas; e elas virão, e verão minha glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 19, 'E porei nelas um sinal; e a uns que delas sobreviverem enviarei às nações: [a] Társis, Pul e Lude; [aos] flecheiros, [a] Tubal e Javã; até as terras costeiras [mais] distantes, que não ouviram minha fama, nem viram minha glória; e anunciarão minha glória entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 20, 'E trarão a todos os vossos irmãos dentre todas as nações [como] oferta ao SENHOR, sobre cavalos, e em carruagens, liteiras, mulas e dromedários, ao meu santo monte, [a] Jerusalém, diz o SENHOR, tal como os filhos de Israel trazem ofertas em vasos limpos à casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 21, 'E também tomarei a alguns deles para [serem] sacerdotes [e] para Levitas,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 22, 'Porque assim como os novos céus e a nova terra, que farei, estarão perante mim,diz o SENHOR, assim também estará vossa descendência e vosso nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 23, 'E será que, desde uma lua nova até a outra, e desde um sábado até o outro, todos virão para adorar perante mim,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 66, 24, 'E sairão, e verão os cadáveres dos homens que se rebelaram contra mim; porque o verme deles nunca morrerá, nem seu fogo se apagará; e serão horríveis a todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 1, 'Palavras de Jeremias, filho de Hilquias, [um] dos sacerdotes que estiveram em Anatote, na terra de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 2, 'Ao qual veio a palavra do SENHOR nos dias de Josias, filho de Amom, rei de Judá, no décimo terceiro ano de seu reinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 3, 'Veio também nos dias de Jeoaquim, filho de Josias, rei de Judá, até o fim do décimo primeiro ano de Zedequias, filho de Josias, rei de Judá, até que Jerusalém foi levada cativa no quinto mês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 4, 'Veio, pois, a palavra do SENHOR a mim, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 5, 'Antes que te formasse no ventre eu te conheci, e antes que saísses do útero eu te santifiquei, te dei por profeta às nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 6, 'E eu disse: Ah! Senhor DEUS! Eis que não sei falar, pois sou um menino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 7, 'Porém o SENHOR me disse: Não digas: sou menino; porque a todos a quem eu te enviar tu irás, e falarás tudo quanto eu te mandar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 8, 'Não temas diante deles, porque estou contigo para te livrar, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 9, 'Então o SENHOR estendeu sua mão, e tocou em minha boca. E o SENHOR me disse: Eis que tenho posto minhas palavras em tua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 10, 'Olha que eu te pus neste dia sobre nações e sobre reinos, para arrancar e para derrubar, e para destruir e para arruinar, e para edificar e para plantar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 11, 'E a palavra do SENHOR veio a mim, dizendo: O que tu vês, Jeremias? E eu disse: Vejo uma vara de amendoeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 12, 'E disse-me o SENHOR: Viste bem; porque eu apresso minha palavra para cumpri-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 13, 'E veio a mim palavra do SENHOR segunda vez, dizendo: O que tu vês? E eu disse: Vejo uma panela fervente; e sua face está voltada para o norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 14, 'Então o SENHOR me disse: Do norte o mal será solto sobre todos os moradores desta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 15, 'Porque eis que eu convoco todas as famílias dos reinos do norte,diz o SENHOR; e virão, e cada um porá seu trono à entrada das portas de Jerusalém, e junto a todos seus muros ao redor, e em todas as cidades de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 16, 'E pronunciarei meus juízos contra eles por causa de toda a sua maldade, pois me deixaram, e queimaram incenso a deuses estranhos, e se encurvaram a objetos de suas [próprias] mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 17, 'Tu pois, prepara tua roupa, e te levanta-te; e fala-lhes tudo quanto eu te mandar; não tenhas medo diante deles, para que eu não te faça ter medo diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 18, 'Porque eis que eu te ponho hoje como cidade fortificada, e como coluna de ferro, e como muro de bronze contra toda esta terra; contra os reis de Judá, seus príncipes, seus sacerdotes, e contra o povo desta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 1, 19, 'E lutarão contra ti, mas não te vencerão; porque eu sou contigo, diz o SENHOR, para te livrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 1, 'E veio a mim palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 2, 'Vai, e clama aos ouvidos de Jerusalém, dizendo: Assim diz o SENHOR: Lembro-me de ti, da [tua] bondade que tinhas em tua juventude, do amor do teu noivado, quando andavas após mim no deserto, em terra não semeada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 3, 'Israel era santidade ao SENHOR, era os primeiros de sua colheita. Todos os que o prejudicavam cometiam pecado [e] o mal vinha sobre eles, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 4, 'Ouvi a palavra do SENHOR, ó casa de Jacó, e todas as famílias da casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 5, 'Assim diz o SENHOR: Que maldade vossos pais acharam em mim, para terem se afastado de mim, [de modo que] seguiram coisas inúteis, e eles [mesmos] se tornarão inúteis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 6, 'Eles nem disseram: Onde está o SENHOR, que nos fez subir de terra do Egito, que nos guiou pelo deserto, por uma terra deserta e esburacada, por uma terra seca e de sombra de morte, por uma terra pela qual ninguém passava, nem ali homem algum habitava?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 7, 'E eu vos trouxe à terra de Carmelo, para que comêsseis seu fruto e seu bem; mas entrastes, e contaminastes minha terra, e fizestes minha propriedade abominável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 8, 'Os sacerdotes não disseram: Onde está o SENHOR? E os que teriam de usar a lei não me conheceram; e os líderes se rebelaram contra mim, e os profetas profetizaram em [nome de] Baal, e seguiram aquilo que não tem proveito algum'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 9, 'Por isso ainda brigarei em juízo convosco, diz o SENHOR, e disputarei com os filhos de vossos filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 10, 'Pois passai às ilhas do Chipre e vede; e enviai [mensageiros] a Quedar, e prestai atenção, e vede se aconteceu alguma coisa semelhante a esta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 11, 'Se alguma nação tenha mudado de deuses, ainda que eles não sejam deuses. Mas meu povo trocou sua glória pelo que não tem proveito algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 12, 'Espantai-vos, céus, por causa disto, e horrorizai-vos; ficai bastante desolados, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 13, 'Pois meu povo fez dois males: deixaram a mim, [que sou] fonte de água viva, para cavarem para si cisternas, cisternas rachadas, que não retêm águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 14, 'Por acaso Israel é um servo? É um escravo de nascimento? Por que, [então] ,ele se tornou uma presa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 15, 'Os filhotes de leão bramaram sobre ele, deram sua voz; e tornaram sua terra uma assolação; suas cidades estão queimadas, sem morador;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 16, 'Até os filhos de Nofe e de Tafnes te quebraram o topo da cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 17, 'Não foi tu mesmo que procuraste isto para ti, de abandonar ao SENHOR teu Deus, enquanto andavas pelo caminho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 18, 'Ora, o que tu tens a ver com o caminho do Egito, para que bebas água do Nilo? E o que tens a ver com o caminho de Assíria, para que bebas água do rio [Eufrates] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 19, 'A tua maldade te castigará e tuas infidelidades te repreenderão; então conhece e vê como é mal e amargo teres abandonado ao SENHOR teu Deus, e não teres tido temor a mim, diz o Senhor DEUS dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 20, 'Pois muito tempo atrás, eu quebrei teu jugo, e rompi tuas amarras, e tu disseste: Não servirei. Porém sobre todo morro alto e abaixo de toda árvore frondosa tu te deitavas [como] prostituta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 21, 'E eu te plantei de boa vide; ela toda era semente confiável. Como, pois, te tornaste para mim ramos de vide estranha?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 22, 'Ainda que te laves com potassa, e passes muito sabão sobre ti, teu pecado está marcado diante de mim, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 23, 'Como podes dizer: Nunca me contaminei, nunca andei atrás dos baalins? Olha o teu caminho no vale; reconhece o que fizeste, ó dromedária ligeira, que anda errante seus percursos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 24, 'jumenta selvagem acostumada ao deserto, que aspira o vento por causa do desejo da alma; de seu cio quem a deteria? Todos os que a buscarem não se cansarão; no mês dela a acharão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 25, 'Impede que teus pés andem descalços, e tua garganta tenha sede. Porém tu disseste: Não há mais esperança; não, porque amo estranhos, e tenho que ir atrás deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 26, 'Tal como o ladrão se envergonha quando é pego, assim se envergonharão os da casa de Israel; eles, seus reis, seus príncipes, seus sacerdotes, e seus profetas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 27, 'Que dizem à madeira: Tu és meu pai; e à pedra: Tu me geraste: pois viraram as costas em minha direção, e não o rosto; porém no tempo de sua angústia dizem: Levanta-te, e livra-nos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 28, 'Onde estão os teus deuses que fizeste para ti? Eles que se levantem, se é que eles podem te livrar no tempo de tua aflição; porque, ó Judá, os teus deuses foram tantos quantos o número de tuas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 29, 'Por que discutis comigo? Todos vós transgredistes contra mim, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 30, 'Em vão afligi vossos filhos; eles não aceitaram correção. Vossa [própria] espada matou vossos profetas como um leão destruidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 31, 'Ó geração, considerai vós a palavra do SENHOR. Por acaso eu fui um deserto ou uma terra de escuridão a Israel? Então por que meu povo tem dito: Somos senhores; nunca mais viremos a ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 32, 'Por acaso a virgem se esquece de seus enfeites, [ou] a noiva de seus adornos? Porém meu povo se esqueceu de mim há inúmeros dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 33, 'Como enfeitas teu caminho para buscar amor! Pois até às malignas ensinaste teus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 34, 'Até nas bordas de tuas roupas se achou o sangue das almas dos pobres inocentes; não o achaste em arrombamento, mas em todas estas coisas.')
